NAMES = ['δε', 'δn', 'δe0', 'δπ0', "δe′", "δπ′"]


def solve(columns):
    A = np.array([[r[i] for i in columns] for r in EQUATIONS])
    b = np.array([r[6] for r in EQUATIONS])
    w = np.array([r[7] for r in EQUATIONS])
    sw = np.sqrt(w)
    x, *_ = np.linalg.lstsq(A * sw[:, None], b * sw, rcond=None)
    res = A @ x - b
    dof = len(b) - len(columns)
    s2 = (w * res ** 2).sum() / dof
    cov = s2 * np.linalg.inv((A * w[:, None]).T @ A)
    return x, np.sqrt(np.diag(cov)), np.sqrt((w * res ** 2).sum() / w.sum())


def main():
    print(f'Le Verrier meridian series, {len(EQUATIONS)} equations of condition (arXiv:1104.0548)')
    x, s, rms = solve([0, 1, 2, 3, 4, 5])
    print('  general solution (all six unknowns):')
    for n, v, e in zip(NAMES, x, s):
        print(f'    {n:4s} = {v:8.3f} ± {e:.3f}')
    print(f'    → perihelion advance δπ′ = {x[5] * 100:.1f} ± {s[5] * 100:.1f} ″/cy   (paper 42.8 ± 12.6; GR 42.98)   weighted rms O−C {rms:.2f}″')
    x5, s5, _ = solve([0, 1, 2, 3, 5])
    print(f'  with δe′ fixed at 0 (Le Verrier\'s assumption): δπ′ = {x5[4] * 100:.1f} ± {s5[4] * 100:.1f} ″/cy')
    print('  These are longitude-reduced positions: no right-ascension rate exists in this chain for a dα/dλ slope to act on.')


if __name__ == '__main__':
    main()
